//! Results generated by the TypeScript engine, not by the implementation under
//! test. `scripts/rust-golden/graph.mjs --write` refreshes them only after a
//! live cross-engine comparison passes.
mod support;

use codegraph_db::Store;
use codegraph_types::{Edge, FileRecord, Node};
use serde::Deserialize;
use serde_json::Value;

#[derive(Deserialize)]
struct Scenario {
    name: String,
    nodes: Vec<Node>,
    edges: Vec<Edge>,
    files: Vec<FileRecord>,
    cases: Vec<Case>,
}

#[derive(Deserialize)]
struct Case {
    query: Value,
    expected: Value,
}

fn compact(value: Value) -> Value {
    match value {
        Value::Object(mut map) if map.contains_key("qualifiedName") && map.contains_key("id") => {
            map.remove("id").unwrap()
        }
        Value::Object(map) => {
            Value::Object(map.into_iter().map(|(k, v)| (k, compact(v))).collect())
        }
        Value::Array(a) => Value::Array(a.into_iter().map(compact).collect()),
        other => other,
    }
}

fn check(name: &str) {
    let scenarios: Vec<Scenario> =
        serde_json::from_str(include_str!("fixtures/golden.json")).unwrap();
    let scenario = scenarios.into_iter().find(|s| s.name == name).unwrap();
    let dir = tempfile::tempdir().unwrap();
    let store = Store::initialize(dir.path().join("codegraph.db")).unwrap();
    store.insert_nodes(&scenario.nodes).unwrap();
    store.insert_edges(&scenario.edges).unwrap();
    for file in &scenario.files {
        store.upsert_file(file).unwrap();
    }
    for case in scenario.cases {
        let actual = compact(support::run_query(&store, &case.query));
        if let Some(diff) = difference(&actual, &case.expected, "result") {
            panic!("{}: {}\n{diff}", scenario.name, case.query);
        }
    }
    // Explicitly close SQLite before TempDir cleanup on Windows.
    store.close().unwrap();
}

fn difference(actual: &Value, expected: &Value, path: &str) -> Option<String> {
    if actual == expected {
        return None;
    }
    match (actual, expected) {
        // JSON has one number type: 11 and 11.0 are the same oracle value.
        // Floating-point scores still compare exactly, without an epsilon.
        (Value::Number(a), Value::Number(b)) if a.as_f64() == b.as_f64() => return None,
        (Value::Array(a), Value::Array(b)) if a.len() == b.len() => {
            for (i, (a, b)) in a.iter().zip(b).enumerate() {
                if let Some(diff) = difference(a, b, &format!("{path}[{i}]")) {
                    return Some(diff);
                }
            }
            return None;
        }
        (Value::Object(a), Value::Object(b))
            if a.len() == b.len() && a.keys().all(|k| b.contains_key(k)) =>
        {
            for (key, a) in a {
                if let Some(diff) = difference(a, &b[key], &format!("{path}.{key}")) {
                    return Some(diff);
                }
            }
            return None;
        }
        _ => {}
    }
    Some(format!("{path}: got {actual}, expected {expected}"))
}

